import csv, hashlib, json, re, subprocess
from pathlib import Path
from collections import deque

ROOT = Path(__file__).resolve().parents[2]
ROOT = ROOT.parent if ROOT.name == '.kunora' else ROOT
U = ROOT / 'duanxian/design/upgrades/duanxian-upg-impl-001'
W = ROOT / '.kunora/acc2-work'
BASE = '92573f1cca40f37cee04d2beb8708ff33ba603d6'
CANDIDATE = '311b29af7fec928ea987c5e469d2389442cd6348'
DEFINITION = '4ce28e8a903adce69579fe08b51bf2b6ff3d842d'
def sha(b): return hashlib.sha256(b).hexdigest()
def git(*args):
    p = subprocess.run(['git', *args], cwd=ROOT, capture_output=True, check=True)
    return p.stdout
def jp(x, pointer):
    for p in pointer.strip('/').split('/'):
        p = p.replace('~1','/').replace('~0','~')
        x = x[int(p)] if isinstance(x,list) else x[p]
    return x
def read(name): return json.loads((U/name).read_text())
def rows(name): return list(csv.DictReader((U/name).open()))
checks=[]
def check(name, ok, evidence):
    checks.append({'id':name,'result':'PASS' if ok else 'FAIL','evidence':evidence})
    print(checks[-1]['result'], name)

manifest=read('manifest.json')
check('candidate_head',git('rev-parse','HEAD').decode().strip()==CANDIDATE,CANDIDATE)
check('branch',git('branch','--show-current').decode().strip()=='remote-agent/duanxian-upg-acc2-001','remote-agent/duanxian-upg-acc2-001')
hash_rows=[]
for x in manifest['files']:
    b=(U/x['path']).read_bytes()
    hash_rows.append({**x,'actual_sha256':sha(b),'actual_bytes':len(b),'match':len(b)==x['bytes'] and sha(b)==x['sha256']})
check('manifest_15_files',len(hash_rows)==15 and all(x['match'] for x in hash_rows),hash_rows)
check('manifest_inventory',set(p.name for p in U.iterdir())==set(x['path'] for x in manifest['files'])|{'manifest.json'},sorted(p.name for p in U.iterdir()))
for label,p,expected in [('definition','outputs/duanxian-upgrade/duanxian-upg-def-001-definition.md',manifest['dependency_refs']['definition_sha256']),('snapshot','.kunora/inputs/open-issues-snapshot-20261114.md',manifest['dependency_refs']['issue_snapshot_sha256'])]:
    b=(ROOT/p).read_bytes()
    check(label+'_hash',sha(b)==expected,{'path':p,'bytes':len(b),'sha256':sha(b)})
check('definition_commit_bytes',(ROOT/'outputs/duanxian-upgrade/duanxian-upg-def-001-definition.md').read_bytes()==git('show',DEFINITION+':outputs/duanxian-upgrade/duanxian-upg-def-001-definition.md'),DEFINITION)

base_paths=git('ls-tree','-rz','--name-only',BASE).decode().strip('\0').split('\0')
changed=git('diff','--name-status',BASE,CANDIDATE).decode().splitlines()
old_changed=[x for x in changed if x.split('\t')[-1] in base_paths]
check('old_tracked_files_unchanged',not old_changed,{'base_count':len(base_paths),'modified_or_deleted_base_files':old_changed})
check('candidate_revision_scope',all(x.startswith('duanxian/design/upgrades/duanxian-upg-impl-001/') for x in git('diff','--name-only','466e397',CANDIDATE).decode().splitlines()),git('diff','--name-only','466e397',CANDIDATE).decode().splitlines())
controls=read('01-control-register.json')['controls']; handoff=read('12-traceability-and-handoff.json')
projection=[]
for i,c in enumerate(controls):
    b=(ROOT/c['source_path']).read_bytes(); pointer=c['source_pointer']; errors=[]
    if sha(b)!=c['source_hash']: errors.append('source_hash')
    if pointer.startswith('/'):
        source=jp(json.loads(b),pointer)
        if isinstance(source,dict):
            for field in ['must_hold','must_not_imply','title','definition','responsibility']:
                if field in source and c.get(field)!=source[field]: errors.append(field)
            expected=set(source.get('source_ids',[]))|({source['id']} if 'id' in source else set())
            if set(c['source_ids'])!=expected: errors.append('source_ids')
        elif c.get('must_hold') != source:
            errors.append('must_hold_string_projection')
    else:
        nums=list(map(int,re.findall(r'\d+',pointer))); lines=b.decode().splitlines()[nums[0]-1:nums[-1]]
        if pointer.startswith('L8'):
            for field in ['must_hold']:
                if c[field] not in '\n'.join(lines): errors.append(field)
    projection.append({'index':i,'control_id':c['control_id'],'source_path':c['source_path'],'pointer':pointer,'errors':errors})
check('control_projection_hash_pointer_fields',all(not x['errors'] for x in projection),projection)
ids={c['control_id'] for c in controls}
check('control_trace_inventory',len(ids)==75 and ids=={c['control_id'] for c in handoff['control_trace']['entries']}, {'registered':len(ids),'trace':len(handoff['control_trace']['entries'])})
events=read('06-causal-and-event-map.json')['events']
unknown=[{'event':e['event_id'],'id':i} for e in events for i in e['source_ids'] if i not in ids]
check('event_control_refs',not unknown,unknown)
full_id_refs=[]
for p in U.iterdir():
    if p.suffix not in ('.json','.md','.csv'): continue
    for ln,line in enumerate(p.read_text().splitlines(),1):
        for token in re.findall(r'UPG-CTRL-[A-Z0-9]+(?:-[A-Z0-9]+)*',line):
            if token not in ids: full_id_refs.append({'path':p.name,'line':ln,'token':token})
check('all_full_control_tokens',not full_id_refs,full_id_refs)
ledger=rows('07-information-ledger.csv')
def time(s):
    m=re.match(r'UPG-E-(\d+)(?:\.(\d+))?',s)
    return (int(m[1]),int(m[2] or 0)) if m else None
time_rows=[]
for x in ledger:
    ts=[time(x[k]) for k in ('sent_at','received_at','earliest_use')]
    time_rows.append({'object_id':x['object_id'],'times':[x[k] for k in ('sent_at','received_at','earliest_use')],'result':'PASS' if all(ts) and ts[0]<=ts[1]<=ts[2] else ('MANUAL' if not all(ts) else 'FAIL')})
check('ledger_numeric_order',not any(x['result']=='FAIL' for x in time_rows),time_rows)

migration=[]; snap=(ROOT/'.kunora/inputs/open-issues-snapshot-20261114.md').read_text()
for i,r in enumerate(rows('03-source-migration.csv'),1):
    old=git('show',BASE+':'+r['old_path']).decode().splitlines()
    n=int(r['line'][1:]); exists=r['target'] in base_paths
    exact=r['old_text']==old[n-1]
    expected_map=re.search(r'`(docs/superpowers/specs/lld/[^`]+)`',old[n-1]) if i<=17 else None
    valid=(exact and exists and expected_map and expected_map[1].replace('docs/superpowers/specs/lld/','duanxian/design/specs/lld/')==r['target'] and r['old_path'] in snap and r['target'] in snap) if i<=17 else True
    migration.append({'row':i,'source':r['old_path'],'source_line':n,'target':r['target'],'target_locator':r['target_locator'],'source_line_exact':exact,'target_exists':exists,'equivalence':r['equivalence'],'declared_status':r['status'],'mechanical_result':'PASS' if valid else 'FAIL','semantic_review_required':i>17})
check('migration_17_paths',len(migration)==22 and all(x['mechanical_result']=='PASS' for x in migration[:17]),migration[:17])

skills=[p for p in base_paths if re.fullmatch(r'engine/skills/novel-[^/]+/SKILL.md',p)]
check('BASE_skill_count',len(skills)==82,{'count':len(skills),'method':'git ls-tree -rz --name-only BASE; exact one-level pattern'})
basenames={n:[p for p in base_paths if Path(p).name==n] for n in ['novel-conception-package.json','development-handoff.json','hld-completion.json']}
check('BASE_machine_absence_only',all(not v for v in basenames.values()),basenames)
attrs=git('check-attr','--cached','text','eol','--','engine/skills/novel-hld-finalizer/SKILL.md','engine/harnesses/novel-hld-autonomous/manifest.yaml','engine/skills/novel-development-baseline-preparer/SKILL.md').decode()
check('attribute_risk_reproduced',attrs.count('unspecified')==6,attrs.splitlines())
adapt=rows('10-text-adaptation-map.csv')
check('writing_not_claimed',len(adapt)==28 and all(x['writing_status']=='PENDING_WRITING' for x in adapt),{'rows':len(adapt),'states':sorted(set(x['writing_status'] for x in adapt))})
secret=re.compile(rb'gh[pousr]_[A-Za-z0-9]{20,}|github_pat_[A-Za-z0-9_]{20,}|glpat-[A-Za-z0-9_-]{15,}')
leaks=[p.name for p in U.iterdir() if p.is_file() and secret.search(p.read_bytes())]
check('candidate_secret_pattern_scan',not leaks,{'matched_paths':leaks,'scope':str(U.relative_to(ROOT))})

authority_hashes=[]
def walk_refs(x):
    if isinstance(x,dict):
        if 'path' in x and 'sha256' in x and (ROOT/x['path']).is_file():
            authority_hashes.append({'path':x['path'],'expected':x['sha256'],'actual':sha((ROOT/x['path']).read_bytes())})
        for v in x.values(): walk_refs(v)
    elif isinstance(x,list):
        for v in x: walk_refs(v)
walk_refs(read('00-baseline-and-authority.json'))
check('authority_local_hashes',all(x['actual']==x['expected'] for x in authority_hashes),authority_hashes)
runpath='duanxian/conception-production/run.py'; runtext=(ROOT/runpath).read_text()
runtime_paths=re.findall(r'engine/skills/novel-[^\"\s]+/scripts/run_v2\.py',runtext)
runtime_refs=[{'path':p,'correct_in_BASE':p in base_paths,'duplicated_engine_in_BASE':('engine/'+p) in base_paths} for p in runtime_paths]
test_refs=[]
for name in ['test_attempt_selection_cli.py','test_topology_review_cli.py','test_line_sequence_review_cli.py']:
    p=ROOT/'duanxian/conception-production/tests'/name
    ls=p.read_text().splitlines()
    test_refs.append({'path':str(p.relative_to(ROOT)),'line12':ls[11],'line13':ls[12],'bad_old_root':('parents[4]' in ls[11] and 'projects' in ls[12])})
check('engineering_7_plus_3_static_only',len(runtime_refs)==7 and all(x['correct_in_BASE'] and not x['duplicated_engine_in_BASE'] for x in runtime_refs) and all(x['bad_old_root'] for x in test_refs),{'runtimes':runtime_refs,'tests':test_refs,'execution':'NOT_RUN: no engineering repair/runtime authorization; static read only'})

source=json.loads((ROOT/'duanxian/conception-approved/human-review-report.json').read_text())
vis=source['visual_models'][4]; dist={'NODE-CHAR-01':0,'NODE-CHAR-02':0}; q=deque(dist)
while q:
    a=q.popleft()
    for e in vis['edges']:
        b=e['to_node_id'] if e['from_node_id']==a else (e['from_node_id'] if e['direction']=='bidirectional' and e['to_node_id']==a else None)
        if b and b not in dist: dist[b]=dist[a]+1; q.append(b)
edge_ids={x for e in vis['edges'] for x in e['source_ids']}
rel_ids=set(source['characters']['relationship_networks'][0]['source_ids'])
graph={'group_node_shortest_distances':dist,'edge_source_relation_count':len(edge_ids),'registered_relations':len(rel_ids),'missing_from_visual_edges':sorted(rel_ids-edge_ids),'note':'Aggregated visual node distances do not prove individual relationship distances; no canonical machine graph available.'}
check('visual_edges_cover_claimed_23_relations',edge_ids==rel_ids,graph)

out={'candidate_commit':CANDIDATE,'definition_commit':DEFINITION,'manifest_sha256':sha((U/'manifest.json').read_bytes()),'checks':checks,'migration_22':migration,'graph':graph,'scope_note':'Mechanical PASS does not establish semantic closure. MANUAL ledger rows are internal/terminal states; cross-object timing reviewed separately.'}
(W/'audit-results.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n')
print('CHECKS',len(checks),'FAILED',sum(x['result']=='FAIL' for x in checks),'MANIFEST',out['manifest_sha256'])
